class Solution:
    def canBeEqual(self, s1: str, s2: str) -> bool:
        return (s1[0] == s2[0] or s1[0] == s2[2]) and (s1[1] == s2[1] or s1[1] == s2[3]) and (s1[2] == s2[2] or s1[2] == s2[0]) and (s1[3] == s2[3] or s1[3] == s2[1])

class Solution:
    def maxSubarrayLength(self, nums: List[int], k: int) -> int:
        from collections import defaultdict

        left = 0
        freq = defaultdict(int)
        max_length = 0

        for right in range(len(nums)):
            freq[nums[right]] += 1

            while freq[nums[right]] > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    del freq[nums[left]]
                left += 1

            max_length = max(max_length, right - left + 1)

        return max_length

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Check if the entire array is already strictly increasing
        if all(nums[i] < nums[i + 1] for i in range(n - 1)):
            return n * (n + 1) // 2

        # Iterate through all possible subarrays
        for i in range(n):
            for j in range(i, n):
                # Create a new array by removing the subarray nums[i:j+1]
                new_nums = nums[:i] + nums[j + 1:]
                # Check if the new array is strictly increasing
                if all(new_nums[k] < new_nums[k + 1] for k in range(len(new_nums) - 1)):
                    count += 1

        return count

class Solution:
    def doesValidArrayExist(self, derived: List[int]) -> bool:
        return sum(derived) % 2 == 0

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        indices_a = [i for i in range(len(s) - len(a) + 1) if s[i:i + len(a)] == a]
        indices_b = [j for j in range(len(s) - len(b) + 1) if s[j:j + len(b)] == b]

        beautiful_indices = []
        for i in indices_a:
            for j in indices_b:
                if abs(j - i) <= k:
                    beautiful_indices.append(i)
                    break

        return sorted(set(beautiful_indices))

class Solution:
    def isFascinating(self, n: int) -> bool:
        concatenated = str(n) + str(2 * n) + str(3 * n)
        return len(concatenated) == 9 and '0' not in concatenated and len(set(concatenated)) == 9

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + 1
            for word in dictionary:
                if s[i - len(word):i] == word:
                    dp[i] = min(dp[i], dp[i - len(word)])

        return dp[n]

class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        occupied = set(nums)
        for f, t in zip(moveFrom, moveTo):
            occupied.remove(f)
            occupied.add(t)
        return sorted(occupied)

class Solution:
    def countInterestingSubarrays(self, nums: List[int], modulo: int, k: int) -> int:
        count = 0
        prefix_sum = 0
        prefix_count = {0: 1}

        for num in nums:
            if num % modulo == k:
                prefix_sum += 1
            target = (prefix_sum - k) % modulo
            count += prefix_count.get(target, 0)
            prefix_count[prefix_sum % modulo] = prefix_count.get(prefix_sum % modulo, 0) + 1

        return count

from typing import List

class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        def sieve_of_eratosthenes(limit):
            is_prime = [True] * (limit + 1)
            is_prime[0] = is_prime[1] = False
            for start in range(2, int(limit**0.5) + 1):
                if is_prime[start]:
                    for multiple in range(start*start, limit + 1, start):
                        is_prime[multiple] = False
            return is_prime

        is_prime = sieve_of_eratosthenes(n)
        prime_pairs = []

        for x in range(2, n // 2 + 1):
            y = n - x
            if is_prime[x] and is_prime[y]:
                prime_pairs.append([x, y])

        return prime_pairs

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        for i in range(len(nums)):
            for j in range(i, len(nums)):
                x, y = nums[i], nums[j]
                if abs(x - y) <= min(x, y):
                    max_xor = max(max_xor, x ^ y)
        return max_xor

class Solution:
    def sumOfPowers(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        dp = [[0] * (k + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for j in range(1, min(i, k) + 1):
                dp[i][j] = dp[i - 1][j] + (nums[i - 1] - nums[i - j]) * dp[i - 1][j - 1]

        return dp[n][k] % MOD

class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        total_cost = sum(nums)
        min_cost = total_cost

        for i in range(1, n):
            total_cost += x
            for j in range(n):
                total_cost = min(total_cost, total_cost - nums[j] + nums[(j + i) % n])
            min_cost = min(min_cost, total_cost)

        return min_cost

class Solution:
    def sumOfPowers(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        if k == n:
            return 0
        if k == 2:
            return sum(abs(nums[i] - nums[i + 1]) for i in range(n - 1)) % MOD
        dp = [[0] * (n + 1) for _ in range(k + 1)]
        dp[0][0] = 1
        for i in range(1, k + 1):
            for j in range(i, n + 1):
                dp[i][j] = (dp[i][j - 1] + dp[i - 1][j - 1] * (nums[j - 1] - nums[j - i])) % MOD
        return dp[k][n]

class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        n = len(points)
        points.sort()

        # Calculate Manhattan distances for all pairs of points
        distances = []
        for i in range(n):
            for j in range(i + 1, n):
                distances.append((abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1]), i, j))

        # Sort distances by the Manhattan distance
        distances.sort()

        # Initialize the minimum maximum distance to a large number
        min_max_distance = float('inf')

        # Iterate through each point to remove it and calculate the maximum distance for the remaining points
        for i in range(n):
            remaining_distances = [d for d, idx1, idx2 in distances if idx1 != i and idx2 != i]
            if remaining_distances:
                max_distance = max(remaining_distances, key=lambda x: x[0])
                min_max_distance = min(min_max_distance, max_distance[0])

        return min_max_distance

class Solution:
    def minGroupsForValidAssignment(self, nums: List[int]) -> int:
        from collections import Counter
        freq = Counter(nums)
        n = len(nums)

        def can_form_groups(group_size):
            groups = 0
            for count in freq.values():
                groups += (count + group_size - 1) // group_size
            return groups

        min_group_size = 1
        max_group_size = min(n, max(freq.values()))

        while min_group_size <= max_group_size:
            mid = (min_group_size + max_group_size) // 2
            if can_form_groups(mid) <= mid:
                max_group_size = mid - 1
            else:
                min_group_size = mid + 1

        return min_group_size

class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        def max_partitions(s, k):
            if len(set(s)) <= k:
                return 1
            partitions = 0
            i = 0
            while i < len(s):
                char_count = {}
                for j in range(i, len(s)):
                    if s[j] in char_count:
                        char_count[s[j]] += 1
                    else:
                        char_count[s[j]] = 1
                    if len(char_count) <= k:
                        continue
                    else:
                        partitions += 1
                        i = j
                        break
                else:
                    partitions += 1
                    break
            return partitions

        max_partitions_original = max_partitions(s, k)
        max_partitions_changed = 0
        for i in range(len(s)):
            for char in 'abcdefghijklmnopqrstuvwxyz':
                if char != s[i]:
                    new_s = s[:i] + char + s[i+1:]
                    max_partitions_changed = max(max_partitions_changed, max_partitions(new_s, k))
        return max(max_partitions_original, max_partitions_changed)

class Solution:
    def sumOfPower(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        suffix_sum = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = (prefix_sum[i] + nums[i]) % MOD

        for i in range(n - 1, -1, -1):
            suffix_sum[i] = (suffix_sum[i + 1] + nums[i]) % MOD

        total_power = 0
        for i in range(n):
            total_power = (total_power + nums[i] * nums[i] * (prefix_sum[i] * suffix_sum[i + 1])) % MOD

        return total_power

class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        max_length = 0
        current_length = 0

        for i in range(len(nums)):
            if nums[i] % 2 == 0 and nums[i] <= threshold:
                if current_length == 0:
                    current_length = 1
                else:
                    if nums[i] % 2 != nums[i - 1] % 2:
                        current_length += 1
                    else:
                        current_length = 1
            else:
                current_length = 0

            max_length = max(max_length, current_length)

        return max_length

class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        answer = [0] * len(queries)

        for i, (index, color) in enumerate(queries):
            if nums[index] != 0:
                if index > 0 and nums[index] == nums[index - 1]:
                    answer[i] += 1
                if index < n - 1 and nums[index] == nums[index + 1]:
                    answer[i] += 1

            nums[index] = color

            if index > 0 and nums[index] == nums[index - 1]:
                answer[i] += 1
            if index < n - 1 and nums[index] == nums[index + 1]:
                answer[i] += 1

        return answer

