def min_operations(t, test_cases):
    results = []
    for n, k, a in test_cases:
        count = 0
        product = 1
        for num in a:
            product *= num
        if product % k == 0:
            results.append(0)
            continue
        for num in a:
            if num % k == 0:
                continue
            if num == 1:
                count += 1
            else:
                count += 1
                break
        results.append(count)
    return results

