from collections import defaultdict, deque

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return True

        if 1 in nums:
            return False

        max_num = max(nums)
        prime_factors = defaultdict(list)

        def sieve_of_eratosthenes(n):
            is_prime = [True] * (n + 1)
            for i in range(2, int(n**0.5) + 1):
                if is_prime[i]:
                    for j in range(i*i, n + 1, i):
                        is_prime[j] = False
            return is_prime

        is_prime = sieve_of_eratosthenes(max_num)

        def get_prime_factors(num):
            factors = []
            for i in range(2, num + 1):
                if num % i == 0 and is_prime[i]:
                    factors.append(i)
                    while num % i == 0:
                        num //= i
            return factors

        for i, num in enumerate(nums):
            factors = get_prime_factors(num)
            for factor in factors:
                prime_factors[factor].append(i)

        graph = defaultdict(list)
        for indices in prime_factors.values():
            for i in range(len(indices) - 1):
                graph[indices[i]].append(indices[i + 1])
                graph[indices[i + 1]].append(indices[i])

        visited = set()
        queue = deque([0])

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)

        return len(visited) == len(nums)

class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        if not nums:
            return 0

        max_product = nums[0]
        min_product = nums[0]
        result = nums[0]

        for num in nums[1:]:
            if num == 0:
                max_product = min_product = result = 0
                continue

            temp_max = max(num, max_product * num, min_product * num)
            min_product = min(num, max_product * num, min_product * num)
            max_product = temp_max

            result = max(result, max_product)

        return result

class Solution:
    def minimizeConcatenatedLength(self, words: List[str]) -> int:
        n = len(words)
        dp = [[float('inf')] * 26 for _ in range(n)]
        dp[0][ord(words[0][-1]) - ord('a')] = len(words[0])

        for i in range(1, n):
            first_char = ord(words[i][0]) - ord('a')
            last_char = ord(words[i][-1]) - ord('a')
            for j in range(26):
                dp[i][last_char] = min(dp[i][last_char], dp[i-1][j] + len(words[i]) - (1 if j == first_char else 0))

        return min(dp[n-1])
